CustomField.formula:
IF(
AND(
ISBLANK(EntityLicense__r.Licensee__r.Name), ISBLANK(EntityLicense__r.Licensee__r.LastName)
)
, EmployeeLicense__r.Licensee__r.FirstName & " "& EmployeeLicense__r.Licensee__r.LastName,
IF(
ISBLANK(EntityLicense__r.Licensee__r.LastName), EntityLicense__r.Licensee__r.Name,
EntityLicense__r.Licensee__r.FirstName & " "& EntityLicense__r.Licensee__r.LastName
)
)
